const D = { n:3, density:.55, energy:.5, glow:.65, hue:16, stars:1, speed:1, scale:1, x:.5, y:.82, style:'dusk', act:'dusk', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI*2;
const u = Math.min(width,height);
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const hw = h => ((h%360)+360)%360;
const clamp = (v,a,b) => v<a?a:(v>b?b:v);

const N = clamp(Math.round(P.n),1,5);
const scl = P.scale;
const cx = P.x*width, groundY = P.y*height;
const showStars = P.stars > 0.5;

// ---- style ----
const H = hw(P.hue);
const STY = {
  dusk:    { mode:'silhouette', body:[135,42,16], rim:[H,72,90], rib:[135,30,30], sky:true, skyTop:[262,55,10], skyMid:[H+8,78,42], skyLow:[H+18,86,60], star:[44,20,98], ground:[H,40,8] },
  linocut: { mode:'lino', body:[0,0,6], rim:[0,0,98], rib:[0,0,98], sky:false, skyTop:[42,10,90], skyMid:[40,14,86], skyLow:[38,16,82], star:[0,0,10], ground:[0,0,6] },
  thermal: { mode:'thermal', body:[240,80,30], rim:[0,90,100], rib:[60,90,100], sky:true, skyTop:[250,70,6], skyMid:[250,60,10], skyLow:[280,50,14], star:[180,60,90], ground:[250,70,6] },
  xray:    { mode:'xray', body:[190,60,50], rim:[190,30,96], rib:[190,50,96], sky:true, skyTop:[205,80,6], skyMid:[200,70,10], skyLow:[195,60,14], star:[190,30,90], ground:[205,70,6] },
  neon:    { mode:'neon', body:[H,90,80], rim:[hw(H+180),90,90], rib:[H,60,90], sky:true, skyTop:[280,80,6], skyMid:[300,70,9], skyLow:[320,70,12], star:[180,80,90], ground:[290,70,6] }
};
const sty = STY[P.style] || STY.dusk;

// ---- cached sky + ground buffer ----
const key = width+'x'+height+':'+scl.toFixed(3)+':'+Math.round(P.hue)+':'+P.style+':'+P.seed+':'+(showStars?1:0)+':'+P.density.toFixed(2);
if (!S.gfx || S.key !== key) {
  const g = S.gfx || (S.gfx = createGraphics(width, height));
  g.colorMode(HSB,360,100,100,100);
  g.clear(); g.push();
  const horizon = groundY;
  if (sty.mode==='lino') {
    // flat cream sky bands (relief-print), hard horizon
    const bands=[0.85,0.9,0.95];
    for (let i=0;i<3;i++){ g.noStroke(); g.fill(sty.skyTop[0], sty.skyTop[1], sty.skyTop[2]-i*4); g.rect(0, i/3*horizon, width, horizon/3+1); }
    g.noStroke(); g.fill(sty.ground[0],sty.ground[1],sty.ground[2]); g.rect(0, horizon, width, height-horizon);
    // carved sun rays
    g.stroke(0,0,10); g.strokeWeight(Math.max(1,u*0.004));
    for (let i=0;i<10;i++){ const a=-Math.PI+ i/9*Math.PI; g.line(width*0.5, horizon*0.55, width*0.5+Math.cos(a)*u*0.6, horizon*0.55+Math.sin(a)*u*0.6); }
    g.noStroke(); g.fill(sty.skyTop[0],sty.skyTop[1],sty.skyTop[2]); g.circle(width*0.5, horizon*0.55, u*0.18);
    g.noFill(); g.stroke(0,0,10); g.strokeWeight(Math.max(1.5,u*0.005)); g.circle(width*0.5, horizon*0.55, u*0.18);
  } else {
    // dusk vertical gradient (dark top -> warm horizon glow)
    const bands=54;
    for (let i=0;i<bands;i++){
      const f=i/(bands-1); const y=f*horizon;
      let c;
      if (f<0.6){ const g2=f/0.6; c=[ lerpA(sty.skyTop[0],sty.skyMid[0],g2), lerpA(sty.skyTop[1],sty.skyMid[1],g2), lerpA(sty.skyTop[2],sty.skyMid[2],g2)]; }
      else { const g2=(f-0.6)/0.4; c=[ lerpA(sty.skyMid[0],sty.skyLow[0],g2), lerpA(sty.skyMid[1],sty.skyLow[1],g2), lerpA(sty.skyMid[2],sty.skyLow[2],g2)]; }
      g.noStroke(); g.fill(hw(c[0]),clamp(c[1],0,100),clamp(c[2],0,100)); g.rect(0,y,width,horizon/bands+1);
    }
    // horizon sun bloom
    g.noStroke();
    for (let i=0;i<5;i++){ g.fill(sty.skyLow[0], sty.skyLow[1]*0.7, sty.skyLow[2]+10, 14-i*2); g.ellipse(cx, horizon, u*(0.5+i*0.35), u*(0.18+i*0.12)); }
    // ground
    g.fill(sty.ground[0],sty.ground[1],sty.ground[2]); g.rect(0,horizon,width,height-horizon);
    g.fill(hw(sty.ground[0]),sty.ground[1],sty.ground[2]+6,50); g.rect(0,horizon,width,u*0.01);
    if (sty.mode==='neon'){ // perspective grid on ground (vaporwave)
      g.stroke(hw(H+180),80,90,50); g.strokeWeight(Math.max(1,u*0.003)); g.noFill();
      for (let i=0;i<10;i++){ const yy=horizon+ (i*i)/81*(height-horizon); g.line(0,yy,width,yy); }
      for (let i=-6;i<=6;i++){ g.line(cx+i*u*0.05, horizon, cx+i*u*0.5, height); }
    }
  }
  // stars baked positions (twinkle applied live), stored
  S.stars = [];
  if (showStars && sty.mode!=='lino'){
    const ns = Math.round(24 + P.density*70);
    for (let i=0;i<ns;i++){ S.stars.push([fr(i*1.7)*width, fr(i*2.9)*horizon*0.72, 0.4+fr(i*3.3)*1.1, fr(i*4.4)]); }
  }
  g.pop();
  S.key = key;
  S.horizon = horizon;
}
function lerpA(a,b,f){ return a+(b-a)*f; }

image(S.gfx, 0, 0);

// ---- act ----
let swayMul=1, owlPeriod=26, shimMul=1;
if (P.act==='windstorm'){ swayMul=2.4; owlPeriod=40; shimMul=1.6; }
else if (P.act==='night'){ swayMul=0.7; owlPeriod=18; shimMul=0.6; }

const horizon = S.horizon!=null?S.horizon:groundY;
const gust = K.pulse*0.5 + A.lowmid*0.6;

// ---- stars twinkle (live, K.t continuous) ----
if (S.stars && S.stars.length){
  push(); blendMode(SCREEN); noStroke();
  for (let i=0;i<S.stars.length;i++){
    const st=S.stars[i];
    const tw = 0.4+0.6*Math.pow(Math.max(0,Math.sin(K.t*(0.8+st[3]*1.6)+st[3]*TAU)),2);
    const spk = i%9===0 ? A.treble*0.6 : 0;
    fill(sty.star[0], sty.star[1], sty.star[2], clamp((30+40*tw+spk*40),0,90));
    circle(st[0], st[1], st[2]*(1+tw*0.6));
  }
  blendMode(BLEND); pop();
}

// ---- heat shimmer band above horizon (continuous drift) ----
if (sty.mode!=='lino'){
  push(); blendMode(SCREEN); noStroke();
  const bandH = u*0.09*shimMul;
  for (let i=0;i<26;i++){
    const f=i/25; const xx=f*width;
    const off = Math.sin(xx*0.03 + K.t*2.0*P.speed)*u*0.006*shimMul + Math.sin(xx*0.011 - K.t*1.3)*u*0.004;
    fill(sty.skyLow[0], sty.skyLow[1]*0.5, sty.skyLow[2]+14, 9);
    ellipse(xx, horizon-bandH*0.3+off, width/22, bandH*0.5);
  }
  blendMode(BLEND); pop();
}

// ---- drifting desert haze/dust (large area, always moving — motion floor) ----
if (sty.mode!=='lino'){
  push(); blendMode(SCREEN); noStroke();
  const NH = 5;
  for (let i=0;i<NH;i++){
    const spd = (0.015+fr(i*6.3)*0.035)*P.speed*shimMul;
    const bx = (fr(i*8.1) + K.t*spd) % 1.4 - 0.2;
    const hx = bx*width*1.2 - width*0.1;
    const hy = horizon - u*(0.02+fr(i*2.7)*0.10) + Math.sin(K.t*0.35+i*1.3)*u*0.015;
    const hwd = u*(0.35+fr(i*4.1)*0.4), hht = u*(0.05+fr(i*3.3)*0.06);
    fill(sty.skyLow[0], sty.skyLow[1]*0.6, sty.skyLow[2]+12, 8);
    ellipse(hx, hy, hwd, hht);
  }
  blendMode(BLEND); pop();
}

// ---- build cactus layout (with sway) ----
const spacing = Math.min(u*0.24*scl, (width*0.9)/Math.max(1,N));
const layout=[];
for (let i=0;i<N;i++){
  const gi = fr(i*11.3+3);
  const xc = cx + (i-(N-1)/2)*spacing + (gi-0.5)*u*0.02;
  const h = u*(0.30+fr(i*5.1)*0.14)*scl;
  const sway = (Math.sin(K.t*0.6*P.speed+i*1.7)*0.6 + Math.sin(K.t*1.4+i)*0.3) * u*0.02*P.energy*swayMul*(1+gust);
  const topx = xc+sway, topy = groundY-h;
  // arm poses: 0-2 arms, seeded personality
  const na = clamp(1 + Math.floor(fr(i*7.7)*(1 + P.density*2.8)), 1, 4); // density -> arm richness
  const arms=[];
  for (let a=0;a<na;a++){
    const side = fr(i*3+a*9)<0.5?-1:1;
    const upH = h*(0.30+fr(i*2+a*4)*0.22);      // height on trunk where arm starts
    const armLen = h*(0.20+fr(i*6+a)*0.16);
    const spread = u*(0.05+fr(i+a*5)*0.05)*scl;
    const bx = xc + sway*(upH/h);               // trunk x at that height
    const by2 = groundY-upH;
    const ex = bx + side*spread;                // elbow
    const ey = by2;
    const tx = ex + sway*0.4;                    // tip (arm rises)
    const ty = ey - armLen;
    arms.push({bx,by2,ex,ey,tx,ty,side});
  }
  layout.push({xc,h,topx,topy,arms});
}

// ---- draw one cactus ----
function limb(x0,y0,x1,y1,x2,y2,tw,fillCol,rimCol){
  // capsule elbow via two round-cap segments + bend
  if (sty.mode==='neon'){
    drawingContext.shadowBlur = 12+P.glow*20; drawingContext.shadowColor='hsla('+Math.round(fillCol[0])+',90%,60%,0.9)';
    noFill(); stroke(fillCol[0],fillCol[1],fillCol[2],90); strokeWeight(tw*0.5); strokeCap(ROUND); strokeJoin(ROUND);
    beginShape(); vertex(x0,y0); vertex(x1,y1); vertex(x2,y2); endShape();
    drawingContext.shadowBlur=0; return;
  }
  strokeCap(ROUND); strokeJoin(ROUND); noFill();
  if (sty.mode==='thermal'){
    const ramp=[[240,85,26],[200,80,44],[130,80,60],[55,90,92],[10,90,100],[0,0,100]];
    for (let r=0;r<ramp.length;r++){ const w=tw*(1-r/ramp.length); stroke(ramp[r][0],ramp[r][1],ramp[r][2],92); strokeWeight(Math.max(1,w));
      beginShape(); vertex(x0,y0); vertex(x1,y1); vertex(x2,y2); endShape(); }
    return;
  }
  if (sty.mode==='xray'){
    stroke(fillCol[0],fillCol[1],fillCol[2],26); strokeWeight(tw);
    beginShape(); vertex(x0,y0); vertex(x1,y1); vertex(x2,y2); endShape();
    stroke(rimCol[0],rimCol[1],rimCol[2],70); strokeWeight(Math.max(1,u*0.0025));
    // internal skeleton line
    beginShape(); vertex(x0,y0); vertex(x1,y1); vertex(x2,y2); endShape();
    return;
  }
  // silhouette / lino: solid body + rim light
  stroke(fillCol[0],fillCol[1],fillCol[2]); strokeWeight(tw);
  beginShape(); vertex(x0,y0); vertex(x1,y1); vertex(x2,y2); endShape();
  // rim light on lit side
  stroke(rimCol[0],rimCol[1],rimCol[2], sty.mode==='lino'?100:80); strokeWeight(Math.max(1.2, tw*(sty.mode==='lino'?0.14:0.2)));
  const ox = tw*0.32*(rimCol===sty.rim?1:1);
  beginShape(); vertex(x0-ox,y0); vertex(x1-ox,y1); vertex(x2-ox,y2); endShape();
}

for (let i=0;i<N;i++){
  const L=layout[i];
  const tw = u*0.045*scl*(0.85+fr(i*13)*0.3);
  push();
  // trunk (slightly bent)
  const midx = (L.xc+L.topx)/2, midy = (groundY+L.topy)/2;
  limb(L.xc, groundY, midx, midy, L.topx, L.topy, tw, sty.body, sty.rim);
  // rounded tip cap
  if (sty.mode!=='neon' && sty.mode!=='xray' && sty.mode!=='thermal'){ noStroke(); fill(sty.body[0],sty.body[1],sty.body[2]); circle(L.topx,L.topy,tw); }
  // arms
  for (let a=0;a<L.arms.length;a++){ const ar=L.arms[a]; limb(ar.bx,ar.by2, ar.ex,ar.ey, ar.tx,ar.ty, tw*0.72, sty.body, sty.rim);
    if (sty.mode!=='neon' && sty.mode!=='xray' && sty.mode!=='thermal'){ noStroke(); fill(sty.body[0],sty.body[1],sty.body[2]); circle(ar.tx,ar.ty,tw*0.72); } }
  // ribs / hatching
  if (sty.mode==='silhouette' || sty.mode==='xray'){
    stroke(sty.rib[0],sty.rib[1],sty.rib[2], sty.mode==='xray'?55:40); strokeWeight(Math.max(1,u*0.0022)); noFill();
    for (let rp=-1;rp<=1;rp++){ line(L.xc+rp*tw*0.28, groundY-tw*0.2, L.topx+rp*tw*0.28, L.topy); }
  }
  if (sty.mode==='xray'){ // water bands
    stroke(sty.rim[0],40,100,50); strokeWeight(Math.max(1,u*0.003));
    for (let b=1;b<6;b++){ const f=b/6; line(L.xc-tw*0.35, groundY-L.h*f, L.topx-tw*0.35, groundY-L.h*f); }
  }
  if (sty.mode==='lino'){ // white carved hatch
    stroke(0,0,98); strokeWeight(Math.max(1,u*0.0022));
    for (let b=0;b<7;b++){ const f=b/7; const yy=groundY-L.h*f; line(L.xc+tw*0.05, yy, L.xc+tw*0.30, yy-tw*0.2); }
  }
  pop();
}

// ---- owl that lands occasionally ----
push();
const oc = (K.t/owlPeriod);
const cyc = oc % 1;
const owlIdx = Math.floor(oc) % Math.max(1,N);
const perchC = layout[owlIdx] || layout[0];
const perch = (perchC.arms.length? perchC.arms[Math.floor(fr(Math.floor(oc)*3.1)*perchC.arms.length)] : null);
const px = perch? perch.tx : perchC.topx;
const py = perch? perch.ty : perchC.topy;
// approach 0..0.18, perched 0.18..0.82, leave 0.82..1
let ox2, oy2, vis=1, wingF=0;
if (cyc<0.18){ const f=cyc/0.18; const side=(fr(Math.floor(oc)*5)<0.5?-1:1); ox2=px+side*(1-f)*width*0.5; oy2=py-(1-f)*u*0.25 - Math.sin(f*Math.PI)*u*0.1; wingF=1-f; vis=clamp(f*3,0,1); }
else if (cyc<0.82){ ox2=px; oy2=py; wingF=Math.max(0, K.pulse*0.3); vis=1; }
else { const f=(cyc-0.82)/0.18; const side=(fr(Math.floor(oc)*8)<0.5?-1:1); ox2=px+side*f*width*0.5; oy2=py-f*u*0.28 - Math.sin(f*Math.PI)*u*0.12; wingF=f; vis=clamp((1-f)*3,0,1); }
const os = u*0.045*scl;
translate(ox2, oy2-os*0.6);
const owlBody = sty.mode==='thermal'?[10,90,100]: sty.mode==='neon'?[hw(H+180),90,95]: sty.mode==='xray'?[190,40,92]:[28,30,26];
const owlEdge = sty.mode==='neon'?[hw(H+120),90,95]:[H,60,80];
noStroke();
// wings (flap on approach/leave)
const wa = wingF*0.9;
fill(owlBody[0],owlBody[1],owlBody[2]*0.9, 90*vis);
push(); rotate(-0.5-wa); ellipse(-os*0.4, 0, os*0.9, os*0.4); pop();
push(); rotate(0.5+wa); ellipse(os*0.4, 0, os*0.9, os*0.4); pop();
// body
fill(owlBody[0],owlBody[1],owlBody[2], 95*vis); ellipse(0, 0, os*0.95, os*1.15);
// ear tufts
triangle(-os*0.32,-os*0.5,-os*0.12,-os*0.5,-os*0.26,-os*0.8);
triangle(os*0.32,-os*0.5,os*0.12,-os*0.5,os*0.26,-os*0.8);
// face disc
fill(owlEdge[0],owlEdge[1]*0.5,owlBody[2]+18,70*vis); ellipse(0,-os*0.12,os*0.7,os*0.6);
// glowing eyes (blink)
const blink = (fr(Math.floor(K.t*1.7))>0.9)?0.15:1;
blendMode(SCREEN);
fill(48,80,100, (60+A.treble*40)*vis);
ellipse(-os*0.2,-os*0.12,os*0.28*blink+os*0.06, os*0.28); ellipse(os*0.2,-os*0.12,os*0.28*blink+os*0.06,os*0.28);
blendMode(BLEND);
fill(0,0,8,95*vis); ellipse(-os*0.2,-os*0.12,os*0.12*blink, os*0.14); ellipse(os*0.2,-os*0.12,os*0.12*blink,os*0.14);
// beak
fill(40,80,80,90*vis); triangle(-os*0.06,-os*0.02, os*0.06,-os*0.02, 0, os*0.12);
pop();

blendMode(BLEND);
